#!/usr/bin/env bash
set -euo pipefail

# ── capture-screenshot.sh ────────────────────────────────────────────
# Capture a screenshot from the running iOS Simulator.
#
# Exit codes:
#   0 = screenshot captured
#   1 = no booted simulator
#   3 = setup error
#
# Usage:
#   ./capture-screenshot.sh --project-dir /path/to/project [--name 'home-screen'] [--device <UDID>]
# ────────────────────────────────────────────────────────────────────

PROJECT_DIR=""
SCREENSHOT_NAME=""
DEVICE_UDID=""

# ── Parse args ─────────────────────────────────────────────────────
while [[ $# -gt 0 ]]; do
  case "$1" in
    --project-dir)  PROJECT_DIR="$2"; shift 2 ;;
    --name)         SCREENSHOT_NAME="$2"; shift 2 ;;
    --device)       DEVICE_UDID="$2"; shift 2 ;;
    *) echo "SCREENSHOT_STATUS:ERROR"; echo "Unknown arg: $1"; exit 3 ;;
  esac
done

if [[ -z "$PROJECT_DIR" ]]; then
  echo "SCREENSHOT_STATUS:ERROR"
  echo "Missing --project-dir"
  exit 3
fi

# ── Setup output directory ─────────────────────────────────────────
SCREENSHOT_DIR="$PROJECT_DIR/.locofy/context"
mkdir -p "$SCREENSHOT_DIR"

# ── Generate filename ──────────────────────────────────────────────
TIMESTAMP=$(date +%Y%m%d_%H%M%S)
if [[ -n "$SCREENSHOT_NAME" ]]; then
  # Sanitize name: replace spaces/special chars with underscores
  SAFE_NAME=$(echo "$SCREENSHOT_NAME" | tr ' /:' '___' | tr -cd '[:alnum:]_-')
  FILENAME="${SAFE_NAME}_${TIMESTAMP}.png"
else
  FILENAME="screenshot_${TIMESTAMP}.png"
fi

OUTPUT_PATH="$SCREENSHOT_DIR/$FILENAME"

# ── Find booted device ─────────────────────────────────────────────
if [[ -z "$DEVICE_UDID" ]]; then
  DEVICE_UDID=$(xcrun simctl list devices booted -j 2>/dev/null \
    | python3 -c "
import json, sys
data = json.load(sys.stdin)
for runtime, devices in data['devices'].items():
    for d in devices:
        if d['state'] == 'Booted':
            print(d['udid']); sys.exit(0)
sys.exit(1)
" 2>/dev/null) || true

  if [[ -z "$DEVICE_UDID" ]]; then
    echo "SCREENSHOT_STATUS:NO_BOOTED_DEVICE"
    echo "No booted simulator found. Launch one first."
    exit 1
  fi
fi

# ── Get device name for display ────────────────────────────────────
DEVICE_NAME=$(xcrun simctl list devices -j 2>/dev/null \
  | python3 -c "
import json, sys
data = json.load(sys.stdin)
udid = '$DEVICE_UDID'
for runtime, devices in data['devices'].items():
    for d in devices:
        if d['udid'] == udid:
            print(d['name']); sys.exit(0)
print('Unknown')
" 2>/dev/null) || true

# ── Capture screenshot ─────────────────────────────────────────────
if ! xcrun simctl io "$DEVICE_UDID" screenshot "$OUTPUT_PATH" 2>/dev/null; then
  echo "SCREENSHOT_STATUS:ERROR"
  echo "Failed to capture screenshot from device $DEVICE_UDID ($DEVICE_NAME)"
  exit 3
fi

# ── Verify file exists ─────────────────────────────────────────────
if [[ ! -f "$OUTPUT_PATH" ]]; then
  echo "SCREENSHOT_STATUS:ERROR"
  echo "Screenshot file not created at $OUTPUT_PATH"
  exit 3
fi

FILE_SIZE=$(stat -f%z "$OUTPUT_PATH" 2>/dev/null || stat -c%s "$OUTPUT_PATH" 2>/dev/null || echo "unknown")

echo "SCREENSHOT_STATUS:SUCCESS"
echo "SCREENSHOT_PATH:$OUTPUT_PATH"
echo "SCREENSHOT_DEVICE:$DEVICE_NAME"
echo "SCREENSHOT_SIZE:$FILE_SIZE bytes"
exit 0
